/* Public access, doctor accounts and payment-gated patient receipts. */
(()=>{
 'use strict';if(!window.RADAZ_PRODUCTION)return;
 const E=R.esc,P=R.platform,X=R.plus,tr=(az,ru,en)=>({az,ru,en}[R.lang]||az);
 const owner=()=>R.state.user?.is_owner||R.state.user?.role==='admin';
 const title=()=>tr('Hesab və şifrə','Учётная запись и пароль','Account and password');
 const clinicsTitle=()=>tr('İşlədiyim klinikalar','Мои клиники','My clinics');
 const button=(label,action,attrs='')=>`<button type="button" class="btn btn-outline btn-sm" data-action="${action}" ${attrs}>${E(label)}</button>`;
 const field=(label,name,value='',extra='')=>`<label class="field">${E(label)}<input name="${name}" value="${E(value)}" ${extra}></label>`;
 const paid=c=>['paid','demo_paid'].includes(c.payment_status);
 const responseMessage=()=>tr('Rapor müraciətinizə 2 saat ərzində cavab veriləcək.','Ответ по вашему заключению будет предоставлен в течение 2 часов.','Your reporting request will receive a response within 2 hours.');
 const testMessage=()=>tr('Ödəniş sınaq rejimindədir. Pul tutulmur.','Оплата в тестовом режиме. Деньги не списываются.','Payment is in test mode. No money is charged.');
 let passwordState=null,paymentState=null,ownerLoading=false;
 const auth=R.authPage;
 R.authPage=register=>{const el=document.createElement('div');el.innerHTML=auth(register);const form=el.querySelector('form');if(register){el.querySelector('.role-select')?.remove();el.querySelectorAll('[name="role"],[name="clinic"]').forEach(n=>n.closest('label')?.remove());form?.insertAdjacentHTML('afterbegin','<input type="hidden" name="role" value="doctor">');const h=el.querySelector('.auth-card h2');if(h)h.textContent=tr('Həkim qeydiyyatı','Регистрация врача','Doctor registration');const pw=el.querySelector('[name="password"]');if(pw){pw.minLength=12;pw.maxLength=128;pw.autocomplete='new-password';pw.closest('label')?.insertAdjacentHTML('afterend',field(tr('Şifrəni təkrar edin','Повторите пароль','Confirm password'),'confirm_password','','type="password" autocomplete="new-password" minlength="12" maxlength="128" required'));}}else{const pw=el.querySelector('[name="password"]');if(pw)pw.autocomplete='current-password';}form?.insertAdjacentHTML('beforeend',button(tr('Şifrəni göstər / gizlət','Показать / скрыть пароль','Show / hide password'),'togglePassword'));return el.innerHTML;};
 R.actions.togglePassword=el=>el.closest('form').querySelectorAll('input[name*="password"]').forEach(i=>i.type=i.type==='password'?'text':'password');
 R.forms.register=async d=>{if(d.password!==d.confirm_password)throw Error(tr('Şifrələr eyni deyil.','Пароли не совпадают.','Passwords do not match.'));await R.api.register({...d,role:'doctor'});R.state.dashTab='profile';R.toast(tr('Həkim hesabınız yaradıldı.','Учётная запись врача создана.','Your doctor account was created.'));R.go('/dashboard');};
 const loginOwner=R.actions.ownerLogin;
 R.actions.ownerLogin=async()=>{const identity=await R.request('/auth/identity');if(!identity.id){location.assign('/signin-with-chatgpt?return_to='+encodeURIComponent('/?admin_login=1#/login'));return;}await loginOwner();R.go('/account');};
 function account(){if(!R.state.user)return R.authPage(false);if(passwordState?.id!==R.state.user.id){const state=passwordState={id:R.state.user.id,loading:true};R.request('/me/password').then(d=>{Object.assign(state,d,{loading:false});if(passwordState===state)R.render();}).catch(e=>{state.error=e.message;state.loading=false;R.render();});}const s=passwordState;return P.accountShell(title(),`<h1>${title()}</h1><section class="card p-settings"><p><strong>${E(R.state.user.email)}</strong></p>${s.loading?R.note(tr('Yüklənir…','Загрузка…','Loading…')):s.error?R.note(E(s.error)):`<p>${s.has_password?tr('Şifrənizi burada dəyişə bilərsiniz.','Здесь можно изменить пароль.','Change your password here.'):tr('Email və şifrə ilə daxil olmaq üçün ilk şifrənizi yaradın.','Создайте пароль для входа по email.','Create your first password to sign in with email.')}</p><form data-form="accountPassword">${s.has_password?field(tr('Cari şifrə','Текущий пароль','Current password'),'current_password','','type="password" autocomplete="current-password" required'):''}${field(tr('Yeni şifrə (ən az 12 simvol)','Новый пароль (не менее 12 символов)','New password (at least 12 characters)'),'password','','type="password" autocomplete="new-password" minlength="12" maxlength="128" required')}${field(tr('Şifrəni təkrar edin','Повторите пароль','Confirm password'),'confirm_password','','type="password" autocomplete="new-password" minlength="12" maxlength="128" required')}<div class="button-row"><button class="btn btn-primary" type="submit">${R.t('Saxla')}</button>${button(tr('Şifrəni göstər / gizlət','Показать / скрыть пароль','Show / hide password'),'togglePassword')}</div></form>`}</section>`);}
 R.forms.accountPassword=async d=>{await R.request('/me/password',{method:'PUT',body:d});passwordState=null;R.render();R.toast(tr('Şifrə saxlanıldı. Email və şifrə ilə daxil ola bilərsiniz.','Пароль сохранён. Теперь можно войти по email.','Password saved. You can now sign in with email.'));};
 const clinicForm=c=>`<form data-form="myClinic">${c?`<input type="hidden" name="id" value="${E(c.id)}">`:''}${field(tr('Klinikanın adı','Название клиники','Clinic name'),'name',c?.name||'','required maxlength="200"')}${field(tr('Ünvan','Адрес','Address'),'address',c?.address||'','maxlength="500"')}${field(tr('Telefon','Телефон','Phone'),'phone',c?.phone||'','type="tel" maxlength="50"')}<button type="submit" class="btn btn-primary">${c?R.t('Saxla'):tr('Klinika əlavə et','Добавить клинику','Add clinic')}</button></form>`;
 function clinics(){return `<section class="card p-settings" id="my-clinics"><h2>${clinicsTitle()}</h2><p>${tr('Profilinizdə göstəriləcək klinikaları əlavə edin.','Добавьте клиники для отображения в вашем профиле.','Add the clinics to display on your profile.')}</p>${(R.state.clinics||[]).map(c=>`<article class="card"><h3>${E(c.name)}</h3><p>${E(c.address||'')}</p><p>${E(c.phone||'')}</p><div class="button-row">${button(tr('Dəyiş','Изменить','Edit'),'editMyClinic',`data-id="${E(c.id)}"`)}${button(tr('Siyahıdan çıxar','Убрать из списка','Remove from list'),'removeMyClinic',`data-id="${E(c.id)}"`)}</div></article>`).join('')}<h3>${tr('Yeni klinika','Новая клиника','New clinic')}</h3>${clinicForm()}</section>`;}
 const profile=R.profileDashboard;R.profileDashboard=()=>{const el=document.createElement('div');el.innerHTML=profile();el.querySelector('[name="clinic"]')?.closest('label')?.remove();return el.innerHTML+clinics();};
 R.clinicDashboard=clinics;
 R.clinicsPage=()=>`<main class="container page p-settings"><h1>${clinicsTitle()}</h1><section class="card"><p>${tr('Klinikaları həkim profilinizdən əlavə edə və idarə edə bilərsiniz.','Добавляйте и управляйте клиниками в профиле врача.','Add and manage clinics from your doctor profile.')}</p><a class="btn btn-primary" href="${R.state.user?'#/dashboard':'#/register'}" ${R.state.user?'data-action="openMyProfile"':''}>${tr('Həkim profilinə keç','Открыть профиль врача','Open doctor profile')}</a></section></main>`;
 R.actions.openMyProfile=async()=>{R.state.dashTab='profile';if(owner())await R.actions.openDoctorCabinet();else R.go('/dashboard');R.render();};
 R.forms.myClinic=async d=>{await R.request(d.id?'/me/clinics/'+encodeURIComponent(d.id):'/clinics',{method:d.id?'PUT':'POST',body:d});R.closeModal();R.state.clinics=await R.api.clinics();await R.refreshPublic();R.render();R.toast(tr('Klinika saxlanıldı.','Клиника сохранена.','Clinic saved.'));};
 R.actions.editMyClinic=el=>{const c=R.state.clinics.find(c=>c.id===el.dataset.id);if(c)R.modal(tr('Klinika məlumatları','Данные клиники','Clinic details'),clinicForm(c));};
 R.actions.removeMyClinic=async el=>{await R.request('/me/clinics/'+encodeURIComponent(el.dataset.id),{method:'DELETE',body:{}});R.state.clinics=await R.api.clinics();await R.refreshPublic();R.render();};
 function paymentBody(c){return `<section class="card"><h2>${E(c.id)}</h2>${paid(c)?`<p class="note" role="status">${responseMessage()}</p>${c.payment_status==='demo_paid'?`<p>${testMessage()}</p>`:''}`:`<p>${tr('Müraciətin göndərilməsini tamamlamaq üçün ödənişi tamamlayın.','Завершите оплату, чтобы отправить заявку.','Complete payment to submit your request.')}</p>${c.payment_status==='demo'?`<p>${testMessage()}</p>${button(tr('Sınaq ödənişini tamamla','Завершить тестовую оплату','Complete test payment'),'completeDemoPayment',`data-id="${E(c.id)}"`)}`:`${button(tr('Ödəniş et','Оплатить','Pay'),'payCase',`data-id="${E(c.id)}"`)} ${button(tr('Ödənişi yoxla','Проверить оплату','Check payment'),'refreshCasePayment',`data-id="${E(c.id)}"`)}`}`}</section>`;}
 R.successPage=()=>{const r=R.state.receipt;if(!r)return `<main class="container page"><a href="#/track">${R.t('Müraciəti izlə')}</a></main>`;return `<main class="container page p-receipt"><h1>${paid(r.case)?tr('Müraciətiniz göndərildi','Заявка отправлена','Request submitted'):tr('Ödənişi tamamlayın','Завершите оплату','Complete payment')}</h1>${paymentBody(r.case)}<section class="card"><h3>${R.t('Gizli giriş açarı')}</h3><code>${E(r.token)}</code><p>${tr('Kodu və gizli açarı saxlayın. Raporunuzu “Müraciəti izlə” səhifəsindən aça bilərsiniz.','Сохраните номер и секретный ключ для отслеживания заключения.','Save your case number and private key to track your report.')}</p><div class="button-row">${button(R.t('Giriş məlumatını saxla'),'downloadReceipt')}<a class="btn btn-primary" href="#/track">${R.t('Müraciəti izlə')}</a></div></section></main>`;};
 const receiptToken=id=>R.state.receipt?.case.id===id?R.state.receipt.token:X.trackCredentials?.id===id?X.trackCredentials.token:undefined;
 R.actions.payCase=async el=>{const id=el.dataset.id;const r=await R.request('/cases/'+encodeURIComponent(id)+'/checkout',{method:'POST',body:{},token:receiptToken(id)});location.assign(r.url);};
 async function updatePayment(id,demo=false){const c=demo?await R.request('/cases/'+encodeURIComponent(id)+'/demo-payment',{method:'POST',body:{},token:receiptToken(id)}):await fetchCase(id);if(R.state.receipt?.case.id===id)R.state.receipt.case=c;if(X.track?.case?.id===id)X.track.case=c;paymentState={id,data:c};R.render();}
 async function fetchCase(id){await R.request('/cases/'+encodeURIComponent(id)+'/payment-status',{token:receiptToken(id)});return R.request('/cases/'+encodeURIComponent(id),{token:receiptToken(id)});}
 R.actions.completeDemoPayment=el=>updatePayment(el.dataset.id,true);
 R.actions.refreshCasePayment=el=>updatePayment(el.dataset.id);
 X.trackBody=()=>{const c=X.track?.case;return c?paymentBody(c)+(c.report?`<section class="card report-paper"><h3>${tr('Radioloji rapor','Радиологическое заключение','Radiology report')}</h3><div class="rich-editor">${R.safeHTML(c.report)}</div></section>`:''):'';};
 function paymentPage(id){if(paymentState?.id!==id){const state=paymentState={id};fetchCase(id).then(c=>{state.data=c;if(paymentState===state)R.render();}).catch(e=>{state.error=e.message;R.render();});}return R.header()+`<main class="container page p-receipt"><h1>${tr('Müraciətin ödənişi','Оплата заявки','Request payment')}</h1>${paymentState.data?paymentBody(paymentState.data):R.note(E(paymentState.error||tr('Yoxlanılır…','Проверяем…','Checking…')))}<a href="#/track">${R.t('Müraciəti izlə')}</a></main>`+R.footer();}
 for(const [key,values] of Object.entries({'Konsultasiya qiyməti (₼) · demo':['Konsultasiya qiyməti (₼)','Стоимость консультации (₼)','Consultation fee (₼)'],'Klinika və PACS':['Klinikalarım','Мои клиники','My clinics'],'Klinika qeydiyyatı':['Həkimin klinikaları','Клиники врача','Doctor clinics']}))['az','ru','en'].forEach((lang,i)=>RADAZ_MESSAGES[lang][key]=values[i]);
 const render=R.render;R.render=()=>{const route=R.state.route;if(route==='/account'){R.$('#app').innerHTML=account();document.title=title()+' · RADAZ';}else if(route.startsWith('/payment/')){R.$('#app').innerHTML=paymentPage(route.split('/')[2]);document.title='RADAZ · '+tr('Ödəniş','Оплата','Payment');}else render();if(R.state.user)R.$$('.dashboard-sidebar nav').forEach(nav=>{if(!nav.querySelector('[href="#/account"]'))nav.insertAdjacentHTML('beforeend',`<a href="#/account">${R.icon('lock',18)} ${title()}</a>`);});if(new URLSearchParams(location.search).has('admin_login')&&!R.state.user&&!ownerLoading&&R.config?.owner_signed_in){ownerLoading=true;R.actions.ownerLogin().catch(R.err).finally(()=>{const u=new URL(location.href);u.searchParams.delete('admin_login');history.replaceState(null,'',u);ownerLoading=false;});}};
 for(const key of ['login','logout','register']){const fn=R.api[key];R.api[key]=async(...args)=>{passwordState=null;paymentState=null;return fn(...args);};}
 if(R.$('#app').children.length)R.render();
})();
